sksl:
uniform shader image;
uniform shader glyphs;
uniform float2 size;
uniform float time;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float4 visible;
uniform float2 glyphCell;
uniform float glyphCount;
uniform float glyphColumns;
uniform float cell;
uniform float charset;
uniform float colorMode;
layout(color) uniform half4 textColor;
uniform float backgroundMode;
layout(color) uniform half4 background;
uniform float contrast;
uniform float brightness;
uniform float invert;
uniform float edges;
half luma(half3 c) { return dot(c, half3(0.2126, 0.7152, 0.0722)); }
half4 tap(float2 q) {
    float3 p = fromLayer * float3(q, 1.0);
    if (abs(p.z) < 1e-6) return half4(0);
    float2 lo = visible.xy + 0.5;
    float2 hi = max(lo, visible.zw - 0.5);
    return image.eval(clamp(p.xy / p.z, lo, hi));
}
half4 main(float2 coord) {
    float3 l = toLayer * float3(coord, 1.0);
    if (abs(l.z) < 1e-6) return half4(0);
    float2 q = l.xy / l.z;
    float cols = max(floor(layer.x / max(cell, 2.0) + 0.5), 1.0);
    float cw = layer.x / cols;
    float rows = max(floor(layer.y / (cw * glyphCell.y / max(glyphCell.x, 1.0)) + 0.5), 1.0);
    float2 box = float2(cw, layer.y / rows);
    float2 o = floor(q / box) * box;
    half4 a = tap(o + box * float2(0.25, 0.25));
    half4 b = tap(o + box * float2(0.75, 0.25));
    half4 c = tap(o + box * float2(0.25, 0.75));
    half4 d = tap(o + box * float2(0.75, 0.75));
    half4 mean = (a + b + c + d) * 0.25;
    if (mean.a < 0.004) return half4(0);
    half3 rgb = mean.rgb / mean.a;
    half tone = saturate((luma(rgb) - 0.5) * half(contrast) + 0.5 + half(brightness));
    if (invert > 0.5) tone = 1.0 - tone;
    float slot = floor(float(tone) * (glyphCount - 1.0) + 0.5);
    if (edges > 0.0) {
        half la = luma(a.rgb), lb = luma(b.rgb), lc = luma(c.rgb), ld = luma(d.rgb);
        half gx = (lb + ld) - (la + lc), gy = (lc + ld) - (la + lb);
        if (length(half2(gx, gy)) > half(mix(1.2, 0.08, edges))) {
            float ax = abs(float(gx)), ay = abs(float(gy));
            slot = glyphCount + (ax > 2.0 * ay ? 0.0 : (ay > 2.0 * ax ? 1.0 : (gx * gy > 0.0 ? 2.0 : 3.0)));
        }
    }
    float2 f = clamp((q - o) / box, 0.5 / glyphCell, 1.0 - 0.5 / glyphCell);
    half cover = glyphs.eval((float2(mod(slot, glyphColumns), floor(slot / glyphColumns)) + f) * glyphCell).a;
    half3 ink = colorMode > 0.5 ? textColor.rgb : rgb / max(max(max(rgb.r, rgb.g), rgb.b), 0.3);
    half inkA = cover * mean.a * (colorMode > 0.5 ? textColor.a : 1.0);
    half backA = backgroundMode > 0.5 ? background.a * mean.a : 0.0;
    return half4(ink * inkA + background.rgb * backA * (1.0 - inkA), inkA + backA * (1.0 - inkA));
}
